 "content": "def transform(grid):
    """Copy the non-seed panel's shape through every panel, tinted by each band's seed."""
    h, w = len(grid), len(grid[0])
    # Separator lines are the uniform full-width/full-height rows and columns.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != 0]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0]
    def spans(n, cuts):
        out, start = [], 0
        for cut in cuts:
            if cut > start:
                out.append((start, cut))
            start = cut + 1
        if start < n:
            out.append((start, n))
        return out
    rs, cs = spans(h, sep_rows), spans(w, sep_cols)
    # Find the prototype pattern in a panel other than the leftmost seed column.
    pattern = None
