    def spans(size, cuts):
        result, start = [], 0
        for cut in cuts:
            if start < cut:
                result.append((start, cut))
            start = cut + 1
        if start < size:
            result.append((start, size))
        return result

    row_spans, col_spans = spans(h, sep_rows), spans(w, sep_cols)
    # The non-seed colored motif is a stencil; the output uses its horizontal mirror.
    source = None
    for r0, r1 in row_spans:
        for ci in range(1, len(col_spans)):
            c0, c1 = col_spans[ci]
            cells = [(r-r0, c-c0) for r in range(r0, r1)
                     for c in range(c0, c1) if grid[r][c] not in (0, grid[0][0])]
            if cells:
                source = (r1-r0, c1-c0, cells)
                break
        if source:
            break
    if source is None:
        return [row[:] for row in grid]

    ph, pw, cells = source
    mirrored = [(dr, pw-1-dc) for dr, dc in cells]
    out = [[0] * w for _ in range(h)]
    for r in sep_rows:
        out[r] = grid[r][:]
    for c in sep_cols:
        for r in range(h):
            out[r][c] = grid[r][c]

    for r0, r1 in row_spans:
        # The seed color for each horizontal band is in the leftmost panel.
        left0, left1 = col_spans[0]
        seed_colors = [grid[r][c] for r in range(r0, r1)
                       for c in range(left0, left1) if grid[r][c] != 0]
        if not seed_colors:
            continue
        color = seed_colors[0]
        for c0, c1 in col_spans:
            for dr, dc in mirrored:
                if r0 + dr < r1 and c0 + dc < c1:
                    out[r0 + dr][c0 + dc] = color
    return out
